import base64
import json

orig_payload_b64 = ''
payload = json.loads(base64.urlsafe_b64decode(orig_payload_b64 + '===').decode('utf-8'))
payload['iat'] = 1771338360
payload['exp'] = 1771339260
new_payload_json = json.dumps(payload, separators=(',', ':'))
new_payload_b64 = base64.urlsafe_b64encode(new_payload_json.encode('utf-8')).decode('utf-8').rstrip('=')
print(new_payload_b64)
